        msg: '已进入编辑模式',
        type: 'info'
      });
    },
    openEditModalWithData(data) {
      console.log('[DEBUG] openEditModalWithData called with data:', data);
      if (!data || !data.imageUrl) {
        const errorMsg = data?.recordId ? '编辑失败：数据库中未找到原始图片数据，请重新分析并保存该图片' : '编辑失败：缺少图片数据';
