      this.showEditModal = true;
      console.log('[DEBUG] showEditModal set to true');
      console.log('[DEBUG] previewUrl length:', this.previewUrl ? this.previewUrl.length : 0);
      console.log('[DEBUG] editCanvasContainer:', this.$refs.editCanvasContainer);
      console.log('[DEBUG] editImg:', this.$refs.editImg);
      this.$nextTick(() => {
        console.log('[DEBUG] in nextTick, editImg:', this.$refs.editImg);
