    },
    generateAnnotatedImage() {
      return new Promise((resolve, reject) => {
        if (!this.previewUrl) {
          reject(new Error('缺少图片数据'));
          return;
        }
        const img = new Image();
        img.onload = () => {
          const exportCanvas = document.createElement('canvas');
          const naturalWidth = this.imageMeta?.width || img.width;
          const naturalHeight = this.imageMeta?.height || img.height;
          exportCanvas.width = naturalWidth;
          exportCanvas.height = naturalHeight;
          const ctx = exportCanvas.getContext('2d');
          ctx.drawImage(img, 0, 0, exportCanvas.width, exportCanvas.height);
          this.editBoxes.forEach((box, i) => {
            const isN = box.x1 <= 1 && box.y1 <= 1;
            let x1, y1, x2, y2;
            if (isN) {
              x1 = box.x1 * exportCanvas.width;
              y1 = box.y1 * exportCanvas.height;
              x2 = (box.x1 + box.x2) * exportCanvas.width;
              y2 = (box.y1 + box.y2) * exportCanvas.height;
            } else {
              x1 = box.x1;
              y1 = box.y1;
              x2 = box.x2;
              y2 = box.y2;
            }
            const width = x2 - x1;
            const cx = (x1 + x2) / 2;
            const cy = (y1 + y2) / 2;

            // 只绘制数字，不绘制方框（与原始识别结果保持一致）
            const label = String(i + 1);
            const fontSize = Math.max(24, Math.min(64, width / 3));
            ctx.font = `bold ${fontSize}px -apple-system, "SF Pro Display", sans-serif`;
            ctx.fillStyle = '#ff3b30';
            ctx.textAlign = 'center';
            ctx.textBaseline = 'middle';
            ctx.fillText(label, cx, cy);
          });
          resolve(exportCanvas.toDataURL('image/jpeg', 0.85));
        };
        img.onerror = () => {
          reject(new Error('图片加载失败'));
        };
        img.src = this.previewUrl;
      });
    },
    // 鼠标按下事件 - 开始绘制或选择框
    onCanvasMouseDown(e) {
      if (!this.isEditMode || !this.hasResult) return;
      const canvas = this.$refs.boxCanvas;
      const rect = canvas.getBoundingClientRect();
      const x = e.clientX - rect.left;
      const y = e.clientY - rect.top;

      // 检查是否点击了某个已有的框
      const boxes = this.result && this.result.boxes ? this.result.boxes : [];
      let clickedBoxIndex = null;
      for (let i = boxes.length - 1; i >= 0; i--) {
        const c = this.resolveCoords(boxes[i], canvas);
        if (x >= c.x1 && x <= c.x2 && y >= c.y1 && y <= c.y2) {
          clickedBoxIndex = i;
          break;
        }
      }
      if (clickedBoxIndex !== null) {
        // 选中已有的框
        this.selectedBoxIndex = clickedBoxIndex;
        this.drawBoxesAnimated();
      } else {
        // 开始绘制新框
        this.isDrawing = true;
        this.drawStart = {
          x,
          y
        };
        this.drawEnd = {
          x,
          y
        };
      }
    },
    // 鼠标移动事件
    onCanvasMouseMove(e) {
      if (!this.isEditMode || !this.hasResult) return;
      if (this.isDrawing && this.drawStart) {
        const canvas = this.$refs.boxCanvas;
        const rect = canvas.getBoundingClientRect();
        this.drawEnd = {
          x: e.clientX - rect.left,
          y: e.clientY - rect.top
        };
        this.drawBoxesAnimated();
      }
    },
    // 鼠标松开事件
    onCanvasMouseUp() {
      if (!this.isEditMode) return;
      if (this.isDrawing && this.drawStart && this.drawEnd) {
        // 完成绘制新框
        const x1 = Math.min(this.drawStart.x, this.drawEnd.x);
        const y1 = Math.min(this.drawStart.y, this.drawEnd.y);
        const x2 = Math.max(this.drawStart.x, this.drawEnd.x);
        const y2 = Math.max(this.drawStart.y, this.drawEnd.y);
        const minSize = 20; // 最小框尺寸

        if (x2 - x1 > minSize && y2 - y1 > minSize) {
          // 将画布坐标转换为原图坐标
          const canvas = this.$refs.boxCanvas;
          const mw = this.imageMeta && this.imageMeta.width || 1;
          const mh = this.imageMeta && this.imageMeta.height || 1;
          const newBox = {
            x1: x1 / canvas.width * mw,
            y1: y1 / canvas.height * mh,
            x2: x2 / canvas.width * mw,
            y2: y2 / canvas.height * mh,
            score: 0.95,
            class_name: 'pig',
            id: Date.now()
          };

          // 添加新框
          if (this.result && this.result.boxes) {
            this.result.boxes.push(newBox);
            this.result.count = this.result.boxes.length;
          }

          // 更新store
          this.$store.commit('SET_RESULT', {
            ...this.result
          });
          this.$store.commit('ADD_LOG', {
            msg: '已添加新识别框',
            type: 'success'
          });
        }
      }
      this.isDrawing = false;
      this.drawStart = null;
      this.drawEnd = null;
      this.drawBoxesAnimated();
    },
    // 删除选中的框
    deleteSelectedBox() {
      if (!this.isEditMode || this.selectedBoxIndex === null) return;
      if (this.result && this.result.boxes) {
        this.result.boxes.splice(this.selectedBoxIndex, 1);
        this.result.count = this.result.boxes.length;
        this.$store.commit('SET_RESULT', {
          ...this.result
        });
        this.$store.commit('ADD_LOG', {
          msg: '已删除识别框',
          type: 'info'
        });
        this.selectedBoxIndex = null;
        this.drawBoxesAnimated();
      }
    },
    // 按Delete键删除选中的框
    handleDeleteKey(e) {
      if (e.key === 'Delete' && this.isEditMode && this.selectedBoxIndex !== null) {
        e.preventDefault();
        this.deleteSelectedBox();
      }
    },
    // 导出带数字标注的图片
    exportAnnotatedImage() {
      if (!this.hasResult) return;
      const canvas = this.$refs.boxCanvas;
      const img = this.$refs.baseImg;
      if (!canvas || !img) return;

      // 创建一个新的canvas用于导出
      const exportCanvas = document.createElement('canvas');
      exportCanvas.width = img.naturalWidth;
      exportCanvas.height = img.naturalHeight;
      const ctx = exportCanvas.getContext('2d');

      // 先绘制原图
      ctx.drawImage(img, 0, 0, exportCanvas.width, exportCanvas.height);

      // 绘制数字序号
      const boxes = this.result && this.result.boxes ? this.result.boxes : [];
      boxes.forEach((box, i) => {
        // 解析坐标（归一化坐标）
        const isN = box.x1 <= 1 && box.y1 <= 1;
        let x1, y1, x2, y2;
        if (isN) {
          x1 = box.x1 * exportCanvas.width;
          y1 = box.y1 * exportCanvas.height;
          x2 = (box.x1 + box.x2) * exportCanvas.width;
          y2 = (box.y1 + box.y2) * exportCanvas.height;
        } else {
          x1 = box.x1;
          y1 = box.y1;
          x2 = box.x2;
          y2 = box.y2;
        }
        const cx = (x1 + x2) / 2;
        const cy = (y1 + y2) / 2;

        // 绘制数字
        const label = String(i + 1);
        const fontSize = Math.max(24, Math.min(48, (x2 - x1) / 3));
        ctx.font = `bold ${fontSize}px -apple-system, "SF Pro Display", sans-serif`;
        ctx.fillStyle = '#000000';
        ctx.textAlign = 'center';
        ctx.textBaseline = 'middle';
        ctx.fillText(label, cx, cy);
      });

      // 下载图片
      const link = document.createElement('a');
      link.download = `pig_count_${Date.now()}.png`;
      link.href = exportCanvas.toDataURL('image/png');
      link.click();
      this.$store.commit('ADD_LOG', {
        msg: '已导出标注图片',
        type: 'success'
      });
    },
    animateNumber(target) {
      const dur = 800;
      const start = Date.now();
      const tick = () => {
        const t = Math.min((Date.now() - start) / dur, 1);
        this.animatedCount = Math.round(target * (1 - Math.pow(1 - t, 4)));
        if (t < 1) requestAnimationFrame(tick);
      };
      requestAnimationFrame(tick);
    },
    getConfClass(score) {
      if (score >= 0.85) return 'conf-high';
      if (score >= 0.65) return 'conf-mid';
      return 'conf-low';
    },
    formatCoord(box) {
      const isN = box.x1 <= 1 && box.y1 <= 1;
      const w = this.imageMeta && this.imageMeta.width || 1;
      const h = this.imageMeta && this.imageMeta.height || 1;
      if (isN) return Math.round(box.x1 * w) + ', ' + Math.round(box.y1 * h) + ', ' + Math.round((box.x1 + box.x2) * w) + ', ' + Math.round((box.y1 + box.y2) * h);
      return Math.round(box.x1) + ', ' + Math.round(box.y1) + ', ' + Math.round(box.x2) + ', ' + Math.round(box.y2);
    },
    async checkServiceHealth() {
      this.checkingService = true;
      try {
        const online = await checkHealth();
        this.$store.commit('SET_SERVICE_STATUS', online);
        this.$store.commit('ADD_LOG', {
          msg: online ? '服务在线' : '服务未响应（Mock 模式）',
          type: online ? 'success' : 'warn'
        });
        // 服务在线时加载猪场列表和统计数据
        if (online) {
          await this.loadFarms();
          await this.loadDetectionStats();
        }
      } catch {
        this.$store.commit('SET_SERVICE_STATUS', false);
      } finally {
        this.checkingService = false;
      }
    },
    // ========== 统计数据方法 ==========
    async loadDetectionStats() {
      try {
        const response = await getDetectionStats(this.selectedFarmId);
        if (response.success) {
          this.systemStats = response.data;
        }
      } catch (err) {
        console.error('加载统计数据失败:', err);
      }
    },
    // ========== 猪场管理方法 ==========
    async loadFarms() {
      try {
        const response = await getFarms();
        if (response.success) {
          this.farms = response.data;
          this.$store.commit('ADD_LOG', {
            msg: `已加载 ${this.farms.length} 个猪场`,
            type: 'info'
          });

          // 检查是否没有养殖场，第一次使用时提示
          if (this.farms.length === 0) {
            this.showToastMessage('第一次使用请先创建养殖场！', 'toast-info', 5000);
          }
        }
      } catch (err) {
        this.$store.commit('ADD_LOG', {
          msg: '加载猪场列表失败：' + err.message,
          type: 'error'
        });
      }
    },
    async onFarmChange() {
      const farm = this.farms.find(f => f.id === this.selectedFarmId);
      if (farm) {
        this.$store.commit('ADD_LOG', {
          msg: `已选择猪场：${farm.name}`,
          type: 'info'
        });
      }
      // 切换猪场后刷新统计数据
      await this.loadDetectionStats();
    },
    closeFarmModal() {
      this.showFarmModal = false;
      this.newFarmName = '';
      this.editingFarmId = null;
      this.editingFarmName = '';
    },
    async addFarm() {
      const name = this.newFarmName.trim();
      if (!name) return;
      this.isAddingFarm = true;
      try {
        const response = await createFarm(name);
        if (response.success) {
          this.farms.unshift(response.data);
          this.newFarmName = '';
          this.$store.commit('ADD_LOG', {
            msg: `成功添加猪场：${response.data.name}`,
            type: 'success'
          });
        }
      } catch (err) {
        this.$store.commit('ADD_LOG', {
          msg: '添加猪场失败：' + err.message,
          type: 'error'
        });
      } finally {
        this.isAddingFarm = false;
      }
    },
    startEditFarm(farm) {
      this.editingFarmId = farm.id;
      this.editingFarmName = farm.name;
      this.$nextTick(() => {
        const input = this.$refs.editInput;
        if (input && input[0]) input[0].focus();
      });
    },
    cancelEditFarm() {
      this.editingFarmId = null;
      this.editingFarmName = '';
    },
    async saveEditFarm() {
      const name = this.editingFarmName.trim();
      if (!name || name === this.farms.find(f => f.id === this.editingFarmId)?.name) {
        this.cancelEditFarm();
        return;
      }
      try {
        const response = await updateFarm(this.editingFarmId, name);
        if (response.success) {
          const index = this.farms.findIndex(f => f.id === this.editingFarmId);
          if (index !== -1) {
            this.farms.splice(index, 1, response.data);
          }
          this.$store.commit('ADD_LOG', {
            msg: `成功更新猪场：${response.data.name}`,
            type: 'success'
          });
        }
      } catch (err) {
        this.$store.commit('ADD_LOG', {
          msg: '更新猪场失败：' + err.message,
          type: 'error'
        });
      } finally {
        this.editingFarmId = null;
        this.editingFarmName = '';
      }
    },
    async deleteFarmById(farmId) {
      const farm = this.farms.find(f => f.id === farmId);
      if (!farm) return;
      if (!confirm(`确定要删除猪场"${farm.name}"吗？`)) return;
      try {
        const response = await deleteFarm(farmId);
        if (response.success) {
          this.farms = this.farms.filter(f => f.id !== farmId);
          if (this.selectedFarmId === farmId) {
            this.selectedFarmId = null;
          }
          this.$store.commit('ADD_LOG', {
            msg: `成功删除猪场：${farm.name}`,
            type: 'success'
          });
        }
      } catch (err) {
        this.$store.commit('ADD_LOG', {
          msg: '删除猪场失败：' + err.message,
          type: 'error'
        });
      }
    },
    formatFarmDate(dateStr) {
      if (!dateStr) return '';
      const date = new Date(dateStr);
      return date.toLocaleDateString('zh-CN', {
        year: 'numeric',
        month: '2-digit',
        day: '2-digit'
      });
    }
  }
};
